// src/tier.ts
init_convexClient();
var cachedTier = null;
var listeners = [];
var OVERRIDE = process.env.SAPIENS_TIER_OVERRIDE;
if (OVERRIDE === "user" || OVERRIDE === "admin") {
  cachedTier = OVERRIDE;
}
function getCachedTier() {
  return cachedTier;
}
function visibleListChanges(prev, next) {
  const filteredPrev = prev === "user";
  const filteredNext = next === "user";
  return filteredPrev !== filteredNext;
}
function setTierFromIsAdmin(isAdmin) {
  if (OVERRIDE) return;
  const next = isAdmin === true ? "admin" : isAdmin === false ? "user" : null;
  const prev = cachedTier;
  cachedTier = next;
  if (visibleListChanges(prev, next)) {
    for (const fn of listeners) {
      try {
        fn();
      } catch {
      }
    }
  }
}
function onTierVisibilityChange(fn) {
  listeners.push(fn);
}
function probeTierInBackground() {
  if (OVERRIDE) return;
  let token;
  try {
    token = getSessionToken();
  } catch {
    return;
  }
  const probe = convexQuery("mcpExtras:mcpGetMySubscription", {
    sessionToken: token
  });
  const timeout = new Promise((_, reject) => {
    const t = setTimeout(() => reject(new Error("tier probe timeout")), 5e3);
    t.unref?.();
  });
  Promise.race([probe, timeout]).then((sub) => {
    if (sub?.user) setTierFromIsAdmin(!!sub.user.isAdmin);
  }).catch(() => {
  });
}

// src/canal.ts
var CANAIS = ["npm", "mcpb", "plugin"];
var pedido = process.env.SAPIENS_MCP_CANAL;
var CANAL = pedido && CANAIS.includes(pedido) ? pedido : "npm";
var MCPB_URL = "https://sapiensinteticos.b-cdn.net/mcpb/sapiens.mcpb";
var PLUGIN_ID = "sapiens-sinteticos@sapiens-sinteticos";
var ENDERECO_SUAS_CHAVES = "https://www.sapiensinteticos.com/conectar-claude#suas-chaves";
function ondeFicaAChave() {
  switch (CANAL) {
    case "mcpb":
      return "No Claude Desktop: Configura\xE7\xF5es, Extens\xF5es, Sapiens Sint\xE9ticos. Os campos da fal e da Kie ficam ali, e o que voc\xEA colar fica guardado no seu computador.";
    case "plugin":
      return 'No Claude Code: /plugin, aba Installed, Sapiens Sint\xE9ticos, "Configure options". Os campos da fal e da Kie ficam ali e v\xE3o pro cofre do sistema; depois, /reload-plugins.';
    default:
      return `No config do cliente MCP, no bloco do sapiens: "env": { "FAL_KEY": "<sua chave da fal>", "KIE_API_KEY": "<sua chave da Kie>" }, e reinicie o cliente. No Claude Code o plugin p\xF5e a chave num campo, e no Claude Desktop a extens\xE3o (.mcpb), sem editar config. Passo a passo: ${ENDERECO_SUAS_CHAVES}`;
  }
}
function comoAtualizar(latest) {
  switch (CANAL) {
    case "mcpb":
      return `Baixar a extens\xE3o nova (${MCPB_URL}) e abrir o arquivo: o Claude Desktop troca a vers\xE3o da extens\xE3o e as chaves j\xE1 guardadas ficam.`;
    case "plugin":
      return `No Claude Code: /plugin, aba Installed, Sapiens Sint\xE9ticos, "Update now" (ou \`claude plugin update ${PLUGIN_ID}\` no terminal) e depois /reload-plugins; as chaves j\xE1 guardadas ficam. Pra n\xE3o ficar pra tr\xE1s de novo: /plugin, aba Marketplaces, sapiens-sinteticos, "Enable auto-update".`;
    default:
      return `Pinar sapiens-mcp@${latest ?? "latest"} na config do MCP, ou limpar o cache do npx e reiniciar o cliente (restart sozinho n\xE3o basta, o cache sobrevive).`;
  }
}

