async function loadCompanion(token) {
  try {
    const c = await convexQuery("companionVoice:mcpGetCompanion", {
      sessionToken: token
    });
    if (!c) return null;
    const offer = c.characterOffer ? { directive: c.characterOffer, characters: c.offerCharacters ?? [] } : null;
    if (c.hasSintetico && c.enabled && c.voiceDirective) {
      return {
        active: true,
        name: c.name ?? null,
        avatarUrl: c.avatarUrl ?? null,
        voiceDirective: c.voiceDirective,
        wearing: c.wearing ?? null,
        offer
      };
    }
    if (c.hasSintetico && !c.enabled && c.inviteDirective) {
      return { active: false, name: c.name ?? null, invite: c.inviteDirective, offer };
    }
    if (offer) return { active: null, offer };
    return null;
  } catch {
    return null;
  }
}
