var searchSchema = external_exports.object({
  query: external_exports.string().describe("Substring pra buscar (min 2 chars)."),
  column: external_exports.string().optional().describe("Default: todos. 'sapiens' (Coluna) ou 'repertorio' (Coluna Repert\xF3rio) s\xE3o os mais usados."),
  format: external_exports.string().optional().describe("Ex 'short', 'essay', 'pop-article', 'long'."),
  status: external_exports.enum(["draft", "published", "archived"]).optional().describe("Default: todos. Use 'published' pra evitar drafts no resultado."),
  tag: external_exports.string().optional().describe("Match exato em tags[] do article. Ex: 'foss', 'estoico', 'sapiens-column'."),
  limit: external_exports.number().int().positive().max(100).optional().describe("Default 30, max 100.")
});
async function search(args) {
  const sessionToken = getSessionToken();
  if (!args.query || args.query.trim().length < 2) {
    return {
      count: 0,
      results: [],
      note: "query muito curta \u2014 passe pelo menos 2 chars"
    };
  }
  return await convexQuery("mcpExtras:mcpSearchArticles", {
    sessionToken,
    query: args.query,
    column: args.column,
    format: args.format,
    status: args.status,
    tag: args.tag,
    limit: args.limit
  });
}

