async function studios(args) {
  if (args.action === "mine") {
    const sessionToken = getSessionToken();
    const studio = await convexAction("desktopMcp:studioMine", { sessionToken });
    if (!studio) {
      return {
        studio: null,
        note: "Voc\xEA ainda n\xE3o fundou um studio. Funde o seu em sapiensinteticos.com/dashboard/studio: ele vira uma p\xE1gina p\xFAblica com a sua obra e o seu time."
      };
    }
    return { studio };
  }
  if (args.action === "list") {
    return {
      count: Object.keys(STUDIOS).length,
      studios: Object.entries(STUDIOS).map(([slug, s]) => ({
        slug,
        ...s
      })),
      note: "Est\xFAdios com mcpReady=true s\xE3o oper\xE1veis direto pelo plugin. mcpReady=false exige UI do dashboard (link no campo url)."
    };
  }
  if (args.action === "get") {
    if (!args.studio) throw new Error("action=get exige 'studio' (slug).");
    const s = STUDIOS[args.studio];
    if (!s) {
      const known = Object.keys(STUDIOS).join(", ");
      throw new Error(
        `Est\xFAdio '${args.studio}' desconhecido. Dispon\xEDveis: ${known}`
      );
    }
    return { slug: args.studio, ...s };
  }
  if (args.action === "publishable_url") {
    const slug = args.slug;
    const pid = args.publishableId;
    if (!slug && !pid) {
      throw new Error("publishable_url exige 'slug' OU 'publishableId'.");
    }
    return {
      url: slug ? `${APP}/articles/${slug}` : null,
      admin: `${APP}/experimentos/content-pipeline`,
      note: slug ? "URL p\xFAblica. Pra ver vers\xF5es anteriores, use sapiens_pipeline list_versions." : "publishableId lookup ainda n\xE3o suportado v1.3. Passe slug."
    };
  }
  if (args.action === "create") {
    const name = (args.name ?? "").trim();
    if (!name) {
      throw new Error(
        "action=create exige 'name' (o nome da casa). Pergunte ao user antes de inventar."
      );
    }
    const sessionToken = getSessionToken();
    const res = await convexMutation("studios:mcpCreateStudio", {
      sessionToken,
      name,
      description: args.description,
      brandSlug: args.brandSlug
    });
    return {
      ...res,
      note: `Studio fundado e J\xC1 NO AR nesse endere\xE7o. O user veste a p\xE1gina (capa, logo, sobre, time, obra) em ${APP}/studios/${res.slug} no modo edi\xE7\xE3o. Convidar gente exige follow m\xFAtuo.`
    };
  }
}

// src/tools/instagram.ts
init_zod();
init_convexClient();
var instagramSchema = external_exports.object({
  action: external_exports.enum(["rules", "rule_upsert", "rule_delete", "inbox", "thread", "send", "posts"]),
  ruleId: external_exports.string().optional().describe("Id da regra (rule_upsert pra editar, rule_delete)."),
  keyword: external_exports.string().optional().describe(
    "Keyword principal da regra (substring case-insensitive por padr\xE3o). Obrigat\xF3ria em regra n\xE3o-fallback (ou use keywords)."
  ),
  keywords: external_exports.array(external_exports.string()).optional().describe("Sin\xF4nimos: a regra casa se QUALQUER um (keyword + keywords) bater. Ex: [site, url]."),
  matchMode: external_exports.enum(["contains", "exact", "starts"]).optional().describe("Como a keyword casa: contains (substring, default) / exact (palavra inteira) / starts (texto come\xE7a com)."),
  trigger: external_exports.enum(["dm", "comment", "story", "all"]).optional().describe("O que dispara: dm / comment / story (resposta a story) / all (default: DM e coment\xE1rio)."),
  reply: external_exports.string().optional().describe("Resposta na DM (obrigat\xF3ria no rule_upsert)."),
  replyVariants: external_exports.array(external_exports.string()).optional().describe("Varia\xE7\xF5es da resposta; presentes, rodam em round-robin no lugar da reply."),
  commentEcho: external_exports.string().optional().describe("Eco p\xFAblico no coment\xE1rio depois da DM ('te respondi no direct!'). S\xF3 p/ coment\xE1rio."),
  echoVariants: external_exports.array(external_exports.string()).optional().describe("Varia\xE7\xF5es do eco p\xFAblico (round-robin)."),
  mediaId: external_exports.string().optional().describe("Escopo por post: id de m\xEDdia do Instagram; a regra s\xF3 casa coment\xE1rio DESSE post."),
  isFallback: external_exports.boolean().optional().describe("Fallback: responde DM sem keyword (1x/24h por pessoa). Nunca dispara em coment\xE1rio."),
  active: external_exports.boolean().optional().describe("Regra ativa (default true)."),
  priority: external_exports.number().optional().describe("Menor casa primeiro (default 100)."),
  igUserId: external_exports.string().optional().describe("IGSID da contraparte (vem do inbox). Pra thread e send."),
  text: external_exports.string().optional().describe("Texto da resposta manual (send)."),
  limit: external_exports.number().optional().describe("M\xE1x de itens (inbox default 30, thread default 40).")
});
async function instagram(args) {
  const sessionToken = getSessionToken();
  switch (args.action) {
    case "rules":
      return await convexQuery("instagramDm:mcpListRules", { sessionToken });
    case "rule_upsert": {
      const reply = need(args.reply, "reply");
      return await convexMutation("instagramDm:mcpUpsertRule", {
        sessionToken,
        ruleId: args.ruleId,
        keyword: args.keyword,
        keywords: args.keywords,
        matchMode: args.matchMode,
        trigger: args.trigger,
        reply,
        replyVariants: args.replyVariants,
        commentEcho: args.commentEcho,
        echoVariants: args.echoVariants,
        mediaId: args.mediaId,
        isFallback: args.isFallback,
        active: args.active,
        priority: args.priority
      });
    }
    case "rule_delete":
      return await convexMutation("instagramDm:mcpRemoveRule", {
        sessionToken,
        ruleId: need(args.ruleId, "ruleId")
      });
    case "inbox":
      return await convexQuery("instagramDm:mcpListThreads", {
        sessionToken,
        limit: args.limit
      });
    case "thread":
      return await convexQuery("instagramDm:mcpThreadMessages", {
        sessionToken,
        igUserId: need(args.igUserId, "igUserId"),
        limit: args.limit
      });
    case "send":
      return await convexAction("instagramDm:mcpSendDm", {
        sessionToken,
        igUserId: need(args.igUserId, "igUserId"),
        text: need(args.text, "text")
      });
    case "posts":
      return await convexAction("instagramDm:mcpListMedia", {
        sessionToken,
        limit: args.limit
      });
  }
}

