var MAX_LOCAL_IMAGE_BYTES = 8 * 1024 * 1024;
function detectImageMime(buf) {
  if (buf.length >= 8 && buf[0] === 137 && buf[1] === 80 && buf[2] === 78 && buf[3] === 71) {
    return "image/png";
  }
  if (buf.length >= 3 && buf[0] === 255 && buf[1] === 216 && buf[2] === 255) {
    return "image/jpeg";
  }
  if (buf.length >= 12 && buf.toString("ascii", 0, 4) === "RIFF" && buf.toString("ascii", 8, 12) === "WEBP") {
    return "image/webp";
  }
  return null;
}
async function readLocalImageAsReference(filePath, role) {
  if (isRemoteContext()) {
    throw new Error(
      `${role}ImagePath (arquivo local) s\xF3 funciona no MCP instalado na sua m\xE1quina (stdio). Na conex\xE3o remota, suba a imagem no site e passe ${role}ImageId (id da galeria) ou ${role}ImageUrl (host Sapiens).`
    );
  }
  const [{ default: fs3 }, { default: path4 }] = await Promise.all([
    import("node:fs/promises"),
    import("node:path")
  ]);
  const abs = path4.resolve(filePath);
  let buf;
  try {
    buf = await fs3.readFile(abs);
  } catch {
    throw new Error(
      `N\xE3o achei/li o arquivo em ${role}ImagePath: "${filePath}". Use o caminho absoluto do arquivo (ex: C:\\Users\\voce\\HERO\\1.png).`
    );
  }
  if (buf.length > MAX_LOCAL_IMAGE_BYTES) {
    const mb = (buf.length / (1024 * 1024)).toFixed(1);
    throw new Error(
      `Imagem de ${role} muito grande (${mb}MB; teto ${Math.round(MAX_LOCAL_IMAGE_BYTES / (1024 * 1024))}MB). Exporte menor e tente de novo.`
    );
  }
  const mimeType = detectImageMime(buf);
  if (!mimeType) {
    throw new Error(
      `O arquivo de ${role} n\xE3o parece PNG/JPEG/WebP ("${filePath}"). O frame inicial/final aceita s\xF3 imagem nesses formatos.`
    );
  }
  return { mimeType, data: buf.toString("base64"), role };
}
async function localFrameReferences(args) {
  const refs = [];
  if (args.startImagePath) {
    if (args.startImageId || args.startImageUrl) {
      throw new Error(
        "Frame inicial: escolha UMA via \u2014 startImagePath (arquivo local) OU startImageId/startImageUrl (galeria/Acervo), n\xE3o as duas."
      );
    }
    refs.push(await readLocalImageAsReference(args.startImagePath, "start"));
  }
  if (args.endImagePath) {
    if (args.endImageId || args.endImageUrl) {
      throw new Error(
        "Frame final: escolha UMA via \u2014 endImagePath (arquivo local) OU endImageId/endImageUrl (galeria/Acervo), n\xE3o as duas."
      );
    }
    refs.push(await readLocalImageAsReference(args.endImagePath, "end"));
  }
  for (const p of args.referenceImagePaths ?? []) {
    refs.push(await readLocalImageAsReference(p, "ref"));
  }
  return refs;
}
async function video(args) {
  if (args.action === "models") {
    const all = await convexQuery("videoModels:listWithOverrides", {});
    const models = (all ?? []).filter((m) => m?.isActive).map((m) => ({
      id: m.id,
      engine: m.engine,
      label: m.label,
      // Família + variante: o Seedance sozinho tem SEIS entradas nesta lista
      // (1.0 Fast, 1.5 Pro, 2.0, 2.0 Fast, 2.0 Mini, 2.5) e são o mesmo motor
      // em geração/tier diferente. Sem os dois campos o cliente lê seis
      // motores sem relação. Ausência = motor sozinho.
      family: m.family ?? null,
      variant: m.variantLabel ?? null,
      // Pra que este motor serve: audio, fala, referencia, movimento, longo.
      bestFor: m.bestFor ?? [],
      // "por-segundo" = o preço MUDA com duração, resolução e (no Kling) áudio.
      // "por-clipe" = preço fixo, config não mexe na conta.
      priceMode: m.priceMode ?? null,
      // O que um create SEM durationSec/resolution debita hoje neste motor,
      // com a config que esse preço paga de fato.
      priceDefault: m.priceDefault ?? null,
      // Os dois cantos do motor: a config mais barata e a mais cara possíveis.
      priceMin: m.priceMin ?? null,
      priceMax: m.priceMax ?? null,
      // +50% no Kling quando o som liga; null = som já embutido no preço.
      audioMultiplier: m.audioMultiplier ?? null,
      modes: m.modes,
      durationsSec: m.durationsSec,
      resolutions: m.resolutions,
      hasAudio: m.hasAudio,
      available: m.available,
      comingSoon: m.comingSoon,
      note: m.description
    }));
    return {
      count: models.length,
      default: "sapiens-video-seedance",
      models,
      note: "N\xC3O EXISTE 'o pre\xE7o' de um motor de v\xEDdeo com priceMode='por-segundo': o custo \xE9 dura\xE7\xE3o x resolu\xE7\xE3o [x \xE1udio], ent\xE3o o que existe \xE9 uma FAIXA. priceDefault.sinapses \xE9 o que um create SEM durationSec e SEM resolution debita hoje (o clamp da casa manda dura\xE7\xE3o ausente pro piso e resolu\xE7\xE3o ausente pro tier MAIS CARO, por isso ele costuma ser bem maior que priceMin). priceMin e priceMax s\xE3o os dois cantos do motor, cada um com a config que o produz. Ao falar de pre\xE7o com a pessoa, diga a faixa e a config, nunca um n\xFAmero solto. Pro n\xFAmero exato de uma config antes de gerar, use action=price (sem custo, sem login): ele devolve o valor que o create vai debitar. Motor com priceMode='por-clipe' (linha Veo, Omni) tem pre\xE7o fixo e as tr\xEAs pontas s\xE3o iguais. available=false = 'em breve' (depende de env, ex: Omni)."
    };
  }
  if (args.action === "price") {
    if (!args.model) {
      throw new Error(
        "action=price exige model (o id do motor; a lista viva sai em action=models)."
      );
    }
    const quote = await convexQuery("videoModels:priceQuote", {
      model: args.model,
      durationSec: args.durationSec,
      resolution: args.resolution,
      audio: args.audio
    });
    const perSecond = quote?.priceMode === "por-segundo";
    const omitiu = perSecond && (args.resolution === void 0 || args.durationSec === void 0) && !quote?.clamped;
    return {
      ...quote,
      note: quote?.clamped ? "ATEN\xC7\xC3O: a config cobrada (billed) n\xE3o \xE9 a que voc\xEA pediu (asked). Dura\xE7\xE3o fora do leque do motor cai no piso e resolu\xE7\xE3o inv\xE1lida cai no tier MAIS CARO, e \xE9 esse valor clampado que o create vai debitar e mandar pro provider. Ajuste o pedido pra um valor que o motor aceita (veja durationsSec/resolutions em action=models)." : omitiu ? "Voc\xEA n\xE3o passou durationSec e/ou resolution, ent\xE3o o servidor preencheu (billed mostra o qu\xEA): dura\xE7\xE3o ausente vira o piso, resolu\xE7\xE3o ausente vira o tier MAIS CARO do motor. O valor em sinapses j\xE1 \xE9 o desse preenchimento, e \xE9 o que o create vai debitar se voc\xEA chamar do mesmo jeito. Passe os dois campos pra pagar o que voc\xEA escolheu." : "sinapses \xE9 o valor que o create vai debitar com exatamente essa config. Confirme com a pessoa antes de gerar."
    };
  }
  if (args.action === "templates") {
    const rows = await convexQuery("videoTemplates:list", {});
    return {
      count: rows?.length ?? 0,
      templates: rows ?? [],
      note: "Passe o slug em action=create como templateSlug: o `prompt` vira s\xF3 a CENA e o `brief` preenche o resto. briefFields diz o que vale a pena preencher em cada receita; allowedModels/allowedDurationsSec s\xE3o o teto do override."
    };
  }
  const sessionToken = getSessionToken();
  if (args.action === "demos") {
    return await convexQuery("videoSpecs:mcpListMyDemoFilms", { sessionToken });
  }
  if (args.action === "film-list") {
    return await convexQuery("videoSpecs:mcpListMyVideoSpecs", {
      sessionToken,
      kind: args.filmKind,
      status: args.filmStatus
    });
  }
  if (args.action === "film-get") {
    if (!args.slug) throw new Error("film-get exige slug (descubra via film-list).");
    return await convexQuery("videoSpecs:mcpGetVideoSpec", { sessionToken, slug: args.slug });
  }
  if (args.action === "caption-list") {
    if (!args.slug) throw new Error("caption-list exige slug (descubra via film-list).");
    return await convexAction("mcpExtrasActions:mcpCaptionList", {
      sessionToken,
      slug: args.slug
    });
  }
  if (args.action === "caption-generate") {
    if (!args.slug) throw new Error("caption-generate exige slug (descubra via film-list).");
    if (!args.captionLang) {
      throw new Error(
        "caption-generate exige captionLang: o idioma FALADO no v\xEDdeo (o modelo transcreve nele)."
      );
    }
    return await convexAction("mcpExtrasActions:mcpCaptionGenerate", {
      sessionToken,
      slug: args.slug,
      lang: args.captionLang,
      trio: args.captionTrio
    });
  }
  if (args.action === "caption-translate") {
    if (!args.slug) throw new Error("caption-translate exige slug (descubra via film-list).");
    if (!args.captionLang) throw new Error("caption-translate exige captionLang (idioma de destino).");
    return await convexAction("mcpExtrasActions:mcpCaptionTranslate", {
      sessionToken,
      slug: args.slug,
      lang: args.captionLang
    });
  }
  if (args.action === "film-upsert") {
    if (!args.spec || typeof args.spec !== "object") {
      throw new Error(
        "film-upsert exige spec (objeto JSON com kind + musicMode + payload do kind: demo | aulaTour | essay | tipoMusical | dataviz)."
      );
    }
    const { kind, musicMode, musicRef, aulaSlug, demo, aulaTour, essay, tipoMusical, dataviz } = args.spec;
    return await convexMutation("videoSpecs:mcpUpsertVideoSpec", {
      sessionToken,
      slug: args.slug,
      kind,
      musicMode: musicMode ?? "default",
      musicRef,
      aulaSlug,
      demo,
      aulaTour,
      essay,
      tipoMusical,
      dataviz
    });
  }
  if (args.action === "film-status") {
    if (!args.slug) throw new Error("film-status exige slug (descubra via film-list).");
    if (args.filmStatus === void 0 && args.videoUrl === void 0 && args.durationSecMeasured === void 0) {
      throw new Error("film-status: passe filmStatus, videoUrl e/ou durationSecMeasured (o fecho do render \xE9 os tr\xEAs).");
    }
    return await convexMutation("videoSpecs:mcpSetVideoStatus", {
      sessionToken,
      slug: args.slug,
      status: args.filmStatus,
      videoUrl: args.videoUrl,
      durationSec: args.durationSecMeasured
    });
  }
  if (args.action === "film-publish") {
    if (!args.slug) throw new Error("film-publish exige slug (descubra via film-list).");
    if (typeof args.published !== "boolean") {
      throw new Error("film-publish exige published (true publica no Acervo, false despublica).");
    }
    return await convexMutation("videoSpecs:mcpSetVideoPublished", {
      sessionToken,
      slug: args.slug,
      published: args.published
    });
  }
  if (args.action === "film-delete") {
    if (!args.slug) throw new Error("film-delete exige slug (descubra via film-list).");
    return await convexMutation("videoSpecs:mcpDeleteVideoSpec", { sessionToken, slug: args.slug });
  }
  if (args.action === "showcase") {
    if (!args.slug) {
      throw new Error("action=showcase exige slug (descubra via action=demos).");
    }
    if (typeof args.showcase !== "boolean") {
      throw new Error("action=showcase exige showcase (true pra p\xF4r, false pra tirar).");
    }
    return await convexMutation("videoSpecs:mcpSetVideoShowcase", {
      sessionToken,
      slug: args.slug,
      showcase: args.showcase,
      showcaseTag: args.showcaseTag,
      showcaseOrder: args.showcaseOrder
    });
  }
  if (args.action === "status") {
    if (!args.imageId) {
      throw new Error("action=status exige imageId (o que create/generate devolveu).");
    }
    return await convexQuery("mcpExtras:mcpVideoStatus", {
      sessionToken,
      imageId: args.imageId
    });
  }
  if (args.action === "sonorize") {
    if (!args.imageId) {
      throw new Error("action=sonorize exige imageId (o clipe SEU, j\xE1 completed, que vai ganhar som).");
    }
    if (!args.prompt || args.prompt.trim().length < 4) {
      throw new Error(
        "action=sonorize exige prompt descrevendo o som da cena (ambiente, materiais, impactos, textura)."
      );
    }
    return await convexAction("mcpExtrasActions:mcpVideoSonorize", {
      sessionToken,
      sourceImageId: args.imageId,
      prompt: args.prompt
    });
  }
  if (args.action === "extend") {
    if (!args.imageId) {
      throw new Error(
        "action=extend exige imageId: o take SEU (j\xE1 completed) que vai ganhar o peda\xE7o seguinte. Pode ser a raiz ou a \xFAltima parte de uma corrente; o servidor resolve a posi\xE7\xE3o."
      );
    }
    return await convexAction("mcpExtrasActions:mcpVideoExtend", {
      sessionToken,
      imageId: args.imageId,
      prompt: args.prompt,
      durationSec: args.durationSec
    });
  }
  if (args.action === "chain") {
    if (!args.imageId) {
      throw new Error("action=chain exige imageId (qualquer parte da corrente serve).");
    }
    return await convexQuery("mcpExtras:mcpVideoChain", {
      sessionToken,
      imageId: args.imageId
    });
  }
  if (args.action === "create") {
    if (!args.model && !args.templateSlug) {
      throw new Error(
        "action=create exige model (ex: sapiens-video-seedance, sapiens-video-kling, sapiens-video-wan, sapiens-video-kling-motion) ou templateSlug (a receita traz o motor; veja action=templates)."
      );
    }
    const localRefs = await localFrameReferences(args);
    const references = localRefs.length ? [...args.references ?? [], ...localRefs] : args.references;
    return await convexAction("mcpExtrasActions:mcpVideoCreateAndRender", {
      sessionToken,
      model: args.model,
      templateSlug: args.templateSlug,
      brief: args.brief,
      prompt: args.prompt,
      aspectRatio: args.aspectRatio,
      durationSec: args.durationSec,
      resolution: args.resolution,
      audio: args.audio,
      references,
      startImageId: args.startImageId,
      startImageUrl: args.startImageUrl,
      endImageId: args.endImageId,
      endImageUrl: args.endImageUrl,
      referenceImageIds: args.referenceImageIds,
      referenceImageUrls: args.referenceImageUrls,
      referenceVideoUrls: args.referenceVideoUrls,
      editOfImageId: args.editOfImageId
    });
  }
  if (args.action === "shadows") {
    if (!args.videoUrl) {
      throw new Error("action=shadows exige videoUrl (URL p\xFAblica do v\xEDdeo-fonte).");
    }
    if (!args.title || args.title.trim().length < 3) {
      throw new Error("action=shadows exige title (m\xEDn. 3 chars; vira o slug do depth map).");
    }
    return await convexAction("mcpExtrasActions:mcpExtractShadows", {
      sessionToken,
      videoUrl: args.videoUrl,
      title: args.title,
      durationSec: args.durationSec
    });
  }
  if (args.action === "shadows-list") {
    return await convexAction("mcpExtrasActions:mcpListShadows", {
      sessionToken,
      search: args.search
    });
  }
  if (args.action === "generate") {
    if (!args.imageId) {
      throw new Error("action=generate exige imageId (v\xEDdeo j\xE1 criado no site).");
    }
    const localRefs = await localFrameReferences(args);
    const references = localRefs.length ? [...args.references ?? [], ...localRefs] : args.references;
    return await convexAction("mcpExtrasActions:mcpVideoGenerate", {
      sessionToken,
      imageId: args.imageId,
      prompt: args.prompt,
      aspectRatio: args.aspectRatio,
      references,
      startImageId: args.startImageId,
      startImageUrl: args.startImageUrl,
      endImageId: args.endImageId,
      endImageUrl: args.endImageUrl
    });
  }
}

// src/tools/write.ts
init_zod();
init_convexClient();
var writeSchema = external_exports.object({
  action: external_exports.enum(["create", "generate", "list", "get", "update", "publish"]),
  // --- create (texto pronto, GRÁTIS) ---
  // title/content são compartilhados com update (declarados lá embaixo).
  category: external_exports.string().optional().describe("create: categoria do artigo (ex: 'filosofia-tech'). Opcional."),
  tags: external_exports.array(external_exports.string()).optional().describe("create: at\xE9 8 tags espec\xEDficas. Opcional."),
  brandSlug: external_exports.string().optional().describe(
    "create: design system que veste a pe\xE7a (slug via sapiens_brand action=list). Omitido, herda o padr\xE3o da tua conta. \xC9 o que faz a capa e as imagens sa\xEDrem no TEU estilo, n\xE3o no da casa."
  ),
  // --- generate ---
  brief: external_exports.string().optional().describe(
    "Briefing livre (1 par\xE1grafo, at\xE9 ~600 palavras). Caminho padr\xE3o de 'generate'. A IA expande na voz Sapiens. Custa 400 Sinapses. Pra texto que VOC\xCA j\xE1 escreveu, use action=create (de gra\xE7a)."
  ),
  sourceKind: external_exports.enum(["brief", "published_article", "user_article"]).optional().describe(
    "Default 'brief'. 'published_article' reescreve um artigo do blog (passe publishedArticleId); 'user_article' reescreve um texto teu (passe sourceUserArticleId)."
  ),
  publishedArticleId: external_exports.string().optional().describe("articles:_id (quando sourceKind='published_article')."),
  sourceUserArticleId: external_exports.string().optional().describe("user_articles:_id (quando sourceKind='user_article')."),
  voiceStyle: external_exports.string().optional().describe("Preset de tom da voz (opcional)."),
  customVoice: external_exports.string().optional().describe("Instru\xE7\xE3o de voz custom (opcional)."),
  voiceSource: external_exports.enum(["sapiens", "minha", "sintetico"]).optional().describe(
    "Qual voz molda o texto: 'sapiens' (default, piso da casa) | 'minha' (a tua alma, destilada do teu rastro) | 'sintetico' (a alma do teu Sint\xE9tico, se tiveres um acordado em Sintonia). Omitido = comportamento igual a 'sapiens'."
  ),
  repertorioItemIds: external_exports.array(external_exports.string()).max(5).optional().describe(
    "At\xE9 5 ids de obras do Repert\xF3rio do usu\xE1rio (repertorioItems:_id) pra IA usar como lente/refer\xEAncia do texto (sinopse + nota do dono entram no prompt). Ache os ids via sapiens_repertorio (action=list/search). S\xF3 do pr\xF3prio usu\xE1rio; ids de outros s\xE3o ignorados."
  ),
  coverImageId: external_exports.string().optional().describe(
    "Capa PRONTA (opcional, vale em create e generate): id de uma imagem da TUA galeria (generatedImages:_id, ache via sapiens_gallery/sapiens_reference) que vira a capa do artigo em vez da capa-cortesia gerada do zero. Use quando voc\xEA J\xC1 gerou a imagem (sapiens_image) e o artigo \xE9 sobre ela: assim a pe\xE7a n\xE3o nasce sem capa se a cortesia falhar."
  ),
  coverImageUrl: httpUrl().optional().describe(
    "Alternativa a coverImageId: URL de imagem do Sapiens (Bunny CDN / Convex) pra usar como capa pronta. Host fora da allowlist \xE9 recusado."
  ),
  // --- list ---
  limit: external_exports.number().int().positive().max(100).optional().describe("Default 50. Max 100. S\xF3 pra action=list."),
  // --- get / update / publish ---
  articleId: external_exports.string().optional().describe("user_articles:_id (obrigat\xF3rio pra get/update/publish)."),
  // --- create / update ---
  title: external_exports.string().optional().describe("Obrigat\xF3rio em create. Em update, renomeia."),
  content: external_exports.string().optional().describe(
    "Markdown completo do corpo. Em create, \xE9 o teu texto na \xEDntegra (nada \xE9 reescrito). Em update, substitui o conte\xFAdo."
  ),
  excerpt: external_exports.string().optional(),
  tldr: external_exports.string().optional(),
  // --- publish ---
  publish: external_exports.boolean().optional().describe(
    "action=publish: true publica no teu perfil (/u/<username>), false volta pra rascunho. Default true."
  )
});
async function write(args) {
  const sessionToken = getSessionToken();
  if (args.action === "create") {
    if (!args.title?.trim()) {
      throw new Error(
        "action=create exige title (o texto \xE9 teu, ent\xE3o o t\xEDtulo tamb\xE9m)."
      );
    }
    const res = await convexMutation("mcpExtras:mcpUserCreateArticle", {
      sessionToken,
      title: args.title,
      content: args.content,
      excerpt: args.excerpt,
      tldr: args.tldr,
      category: args.category,
      tags: args.tags,
      brandSlug: args.brandSlug,
      coverImageId: args.coverImageId,
      coverImageUrl: args.coverImageUrl
    });
    return {
      ...res,
      note: "Salvo como RASCUNHO, sem custo e sem uma linha reescrita. Pra ir ao ar no perfil: action=publish com este articleId."
    };
  }
  if (args.action === "generate") {
    const sourceKind = args.sourceKind ?? "brief";
    if (sourceKind === "brief" && (!args.brief || args.brief.trim().length < 20)) {
      throw new Error(
        "Pra gerar a partir de brief, escreve pelo menos 1 par\xE1grafo (>=20 chars)."
      );
    }
    if (sourceKind === "published_article" && !args.publishedArticleId) {
      throw new Error(
        "sourceKind='published_article' exige publishedArticleId."
      );
    }
    if (sourceKind === "user_article" && !args.sourceUserArticleId) {
      throw new Error("sourceKind='user_article' exige sourceUserArticleId.");
    }
    return await convexAction("userArticlesActions:mcpUserGenerateArticle", {
      sessionToken,
      sourceKind,
      brief: args.brief,
      publishedArticleId: args.publishedArticleId,
      sourceUserArticleId: args.sourceUserArticleId,
      voiceStyle: args.voiceStyle,
      customVoice: args.customVoice,
      voiceSource: args.voiceSource,
      repertorioItemIds: args.repertorioItemIds,
      coverImageId: args.coverImageId,
      coverImageUrl: args.coverImageUrl
    });
  }
  if (args.action === "list") {
    return await convexQuery("mcpExtras:mcpUserListArticles", {
      sessionToken,
      limit: args.limit ?? 50
    });
  }
  if (args.action === "get") {
    if (!args.articleId) throw new Error("action=get exige articleId.");
    return await convexQuery("mcpExtras:mcpUserGetArticle", {
      sessionToken,
      articleId: args.articleId
    });
  }
  if (args.action === "update") {
    if (!args.articleId) throw new Error("action=update exige articleId.");
    return await convexMutation("mcpExtras:mcpUserUpdateArticle", {
      sessionToken,
      articleId: args.articleId,
      title: args.title,
      content: args.content,
      excerpt: args.excerpt,
      tldr: args.tldr
    });
  }
  if (args.action === "publish") {
    if (!args.articleId) throw new Error("action=publish exige articleId.");
    return await convexMutation("mcpExtras:mcpUserPublishArticle", {
      sessionToken,
      articleId: args.articleId,
      publish: args.publish ?? true
    });
  }
}

