// src/tools/voiceJp.ts
init_zod();
init_convexClient();
var voiceJpSchema = external_exports.object({
  action: external_exports.enum(["speak", "status", "list", "queue", "models"]).describe(
    "speak = enfileira e espera o \xE1udio; status = 1 job por id; list = hist\xF3rico; queue = sa\xFAde da fila (worker vivo?); models = cat\xE1logo + limites + as notas de uso."
  ),
  text: external_exports.string().optional().describe(
    "O que vai ser falado, EM JAPON\xCAS (obrigat\xF3rio em speak). Outra l\xEDngua sai como leitura errada. Teto de 300 caracteres: texto maior vira v\xE1rios takes."
  ),
  caption: external_exports.string().optional().describe(
    "Estilo da fala, em japon\xEAs. CURTO ganha: caption longo e descritivo empurra a voz pro agudo neste motor. Pra registro grave (seinen), prefira omitir e variar a seed."
  ),
  modelId: external_exports.string().optional().describe("id do cat\xE1logo (action=models). Default: irodori-4-1-anime."),
  seed: external_exports.number().int().nonnegative().optional().describe(
    "Trava a identidade da voz. Sem seed o worker sorteia e devolve a usada em usedSeed: \xE9 assim que se repete a MESMA voz num pr\xF3ximo take."
  ),
  numSteps: external_exports.number().int().optional().describe("Passos de amostragem, 8 a 120. Default 40; abaixo disso a fala perde defini\xE7\xE3o e o ganho de tempo \xE9 pequeno."),
  cfgScaleText: external_exports.number().optional().describe("Ader\xEAncia ao texto. Default 3."),
  cfgScaleCaption: external_exports.number().optional().describe(
    "For\xE7a do caption. Default 4. Subir N\xC3O conserta caption que desobedece (medimos 4 -> 7 sem mudan\xE7a): reescreva o caption menor."
  ),
  cfgScaleSpeaker: external_exports.number().optional().describe("Ader\xEAncia \xE0 voz. Default 5."),
  wait: external_exports.boolean().optional().describe(
    "Default true: espera o worker terminar e j\xE1 devolve a audioUrl. false devolve s\xF3 o jobId, pra voc\xEA seguir e checar depois com action=status."
  ),
  waitSeconds: external_exports.number().int().positive().max(180).optional().describe("Quanto esperar em speak. Default 60. Estourar n\xE3o perde o job: ele continua na fila."),
  jobId: external_exports.string().optional().describe("obrigat\xF3rio em action=status."),
  status: external_exports.enum(["pending", "claimed", "completed", "error"]).optional().describe("Filtra o hist\xF3rico (action=list)."),
  limit: external_exports.number().int().positive().max(100).optional().describe("Default 20, max 100 (action=list).")
});
var sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function voiceJp(args) {
  const sessionToken = getSessionToken();
  if (args.action === "models") {
    return await convexQuery("voiceJp:mcpModels", { sessionToken });
  }
  if (args.action === "queue") {
    const health = await convexQuery("voiceJp:mcpQueueHealth", { sessionToken });
    const paradoHa = health?.ultimoTakeCompletoMs;
    const workerProvavelmenteVivo = typeof paradoHa === "number" ? paradoHa < 15 * 60 * 1e3 : health?.pendentes === 0;
    return {
      ...health,
      leitura: workerProvavelmenteVivo ? "Worker parece vivo." : "Nenhum take fechou nos \xFAltimos 15 min. O worker pode estar desligado: confirme antes de enfileirar em s\xE9rie."
    };
  }
  if (args.action === "status") {
    if (!args.jobId) throw new Error("action=status exige jobId.");
    return await convexQuery("voiceJp:mcpStatus", { sessionToken, jobId: args.jobId });
  }
  if (args.action === "list") {
    return await convexQuery("voiceJp:mcpList", {
      sessionToken,
      limit: args.limit,
      status: args.status
    });
  }
  if (!args.text) throw new Error("action=speak exige text (em japon\xEAs).");
  const enqueued = await convexMutation("voiceJp:mcpEnqueue", {
    sessionToken,
    text: args.text,
    caption: args.caption,
    modelId: args.modelId,
    seed: args.seed,
    numSteps: args.numSteps,
    cfgScaleText: args.cfgScaleText,
    cfgScaleCaption: args.cfgScaleCaption,
    cfgScaleSpeaker: args.cfgScaleSpeaker
  });
  if (args.wait === false) {
    return {
      ...enqueued,
      dica: "Job na fila. Chame action=status com este jobId pra pegar a audioUrl."
    };
  }
  const teto = (args.waitSeconds ?? 60) * 1e3;
  const inicio = Date.now();
  let espera = 1e3;
  while (Date.now() - inicio < teto) {
    await sleep(espera);
    espera = Math.min(5e3, Math.round(espera * 1.4));
    const job = await convexQuery("voiceJp:mcpStatus", { sessionToken, jobId: enqueued.jobId });
    if (job?.status === "completed") {
      return { ...job, esperouSegundos: Math.round((Date.now() - inicio) / 1e3) };
    }
    if (job?.status === "error") {
      throw new Error(`Gera\xE7\xE3o falhou: ${job.errorMessage || "sem detalhe"}`);
    }
  }
  return {
    jobId: enqueued.jobId,
    status: "pending",
    aviso: `Passou de ${args.waitSeconds ?? 60}s sem fechar. O job N\xC3O foi perdido, segue na fila. Cheque action=status, e action=queue pra ver se o worker est\xE1 de p\xE9.`
  };
}

