import { AsyncLocalStorage as AsyncLocalStorage2 } from "node:async_hooks";
var MAX = 120;
var requestClient = new AsyncLocalStorage2();
function sanitizeClientName(raw) {
  if (typeof raw !== "string") return void 0;
  const clean = raw.replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s+/g, " ").trim();
  if (!clean) return void 0;
  return clean.slice(0, MAX);
}
function runWithClientHint(hint, fn) {
  const clean = sanitizeClientName(hint);
  if (!clean) return fn();
  return requestClient.run(clean, fn);
}
function getClientName() {
  return requestClient.getStore();
}

