var APP3 = "https://sapiensinteticos.com";
async function resolveUser(sessionToken) {
  const user = await convexQuery("desktopAuth:getDesktopUser", { sessionToken });
  if (!user || !user._id) {
    throw new Error(
      "Sess\xE3o Sapiens inv\xE1lida ou expirada. Rode sapiens_meta action=login pra reconectar."
    );
  }
  return user;
}
function mapBadges(rows) {
  return (rows || []).map((b) => ({
    name: b?.badge?.name ?? null,
    description: b?.badge?.description ?? null,
    xpReward: b?.badge?.xpReward ?? null,
    earnedAt: b?.earnedAt ?? b?.awardedAt ?? b?._creationTime ?? null
  }));
}
function mapTools(rows) {
  return (rows || []).filter(Boolean).map((t) => ({
    name: t?.name ?? null,
    slug: t?.slug ?? null,
    category: t?.category ?? t?.categorySlug ?? null,
    url: t?.websiteUrl ?? t?.url ?? null
  }));
}
async function profile(args) {
  const sessionToken = getSessionToken();
  if (args.action === "voz" || args.action === "soul") {
    const voz = await convexQuery("soulContract:getForToken", { sessionToken });
    return {
      ...voz,
      note: "Snapshot datado (generatedAt), n\xE3o \xE9 conex\xE3o viva. Salve como sapiens-voz.json no projeto do usu\xE1rio, ou instale como skill (minha-voz); pra atualizar, rode a action de novo e sobrescreva o arquivo." + (args.action === "soul" ? " AVISO: action=soul foi renomeada pra action=voz. Soul agora \xE9 s\xF3 do Sint\xE9tico: sapiens_sintetico action=soul." : "")
    };
  }
  if (args.action === "notifications") {
    const res = await convexQuery("notifications:mcpListMine", {
      sessionToken,
      ...typeof args.limit === "number" ? { limit: args.limit } : {}
    });
    return {
      ...res,
      note: "Pra marcar lida: action=mark_read (com notificationId pra uma s\xF3, ou sem pra todas)."
    };
  }
  if (args.action === "mark_read") {
    const res = await convexMutation("notifications:mcpMarkRead", {
      sessionToken,
      ...args.notificationId?.trim() ? { notificationId: args.notificationId.trim() } : {}
    });
    return {
      ...res,
      note: args.notificationId ? "Notifica\xE7\xE3o marcada como lida." : `Marquei ${res.updated} notifica\xE7\xE3o(\xF5es) como lida(s).`
    };
  }
  if (args.action === "follow" || args.action === "unfollow") {
    if (!args.followingId?.trim()) {
      throw new Error(
        `action=${args.action} exige followingId (users:_id de quem seguir). Descubra via sapiens_community participants/search_users.`
      );
    }
    const fn = args.action === "follow" ? "users:mcpFollowUser" : "users:mcpUnfollowUser";
    const res = await convexMutation(fn, {
      sessionToken,
      followingId: args.followingId.trim()
    });
    return { ...res, action: args.action };
  }
  if (args.action === "update_bio") {
    if (typeof args.bio !== "string") {
      throw new Error("action=update_bio exige bio (o novo texto do perfil).");
    }
    const res = await convexMutation("users:mcpUpdateBio", {
      sessionToken,
      bio: args.bio
    });
    return { ...res, note: "Bio atualizada." };
  }
  if (args.action === "update_username") {
    if (!args.newUsername?.trim()) {
      throw new Error("action=update_username exige newUsername (3-20 chars).");
    }
    const res = await convexMutation("users:mcpUpdateUsername", {
      sessionToken,
      newUsername: args.newUsername.trim()
    });
    return res;
  }
  if (args.action === "favorite_lists") {
    return await convexQuery("aitag/favorites:mcpListFavoriteLists", { sessionToken });
  }
  if (args.action === "favorite_tool") {
    if (!args.toolId?.trim()) {
      throw new Error("action=favorite_tool exige toolId (via sapiens_repertorio action=search_tools).");
    }
    return await convexMutation("aitag/favorites:mcpToggleFavorite", {
      sessionToken,
      toolId: args.toolId.trim()
    });
  }
  if (args.action === "create_favorite_list") {
    if (!args.listName?.trim()) {
      throw new Error("action=create_favorite_list exige listName.");
    }
    return await convexMutation("aitag/favorites:mcpCreateFavoriteList", {
      sessionToken,
      name: args.listName.trim(),
      emoji: args.emoji,
      description: args.description,
      isPublic: args.isPublic
    });
  }
  if (args.action === "add_to_favorite_list" || args.action === "remove_from_favorite_list") {
    if (!args.toolId?.trim() || !args.listId?.trim()) {
      throw new Error(`action=${args.action} exige toolId e listId (listId via action=favorite_lists).`);
    }
    const fn = args.action === "add_to_favorite_list" ? "aitag/favorites:mcpAddToFavoriteList" : "aitag/favorites:mcpRemoveFromFavoriteList";
    return await convexMutation(fn, {
      sessionToken,
      toolId: args.toolId.trim(),
      listId: args.listId.trim()
    });
  }
  if (args.action === "delete_favorite_list") {
    if (!args.listId?.trim()) {
      throw new Error("action=delete_favorite_list exige listId (via action=favorite_lists).");
    }
    return await convexMutation("aitag/favorites:mcpDeleteFavoriteList", {
      sessionToken,
      listId: args.listId.trim()
    });
  }
  const user = await resolveUser(sessionToken);
  const userId = user._id;
  if (args.action === "badges") {
    const rows = await convexQuery("gamification:getUserBadges", { userId });
    const badges2 = mapBadges(rows);
    return { count: badges2.length, badges: badges2 };
  }
  if (args.action === "golden_tools") {
    const rows = await convexQuery("aitag/favorites:listFavoritesByUserId", {
      userId
    });
    const tools2 = mapTools(rows);
    return {
      count: tools2.length,
      tools: tools2,
      note: "Favoritos do aitag (golden tools). Marque/desmarque pelo aitag.app."
    };
  }
  const [badgeRows, toolRows] = await Promise.all([
    convexQuery("gamification:getUserBadges", { userId }),
    convexQuery("aitag/favorites:listFavoritesByUserId", { userId })
  ]);
  const badges = mapBadges(badgeRows);
  const tools = mapTools(toolRows);
  return {
    identity: {
      username: user.username ?? null,
      name: user.name ?? null,
      avatarUrl: user.avatarUrl ?? user.image ?? null,
      level: user.level ?? null,
      xp: user.xp ?? null,
      isPremium: user.isPremium === true,
      profileUrl: user.username ? `${APP3}/u/${user.username}` : null
    },
    credits: typeof user.totalCredits === "number" ? user.totalCredits : null,
    badges: {
      count: badges.length,
      items: badges.slice(0, 30)
    },
    goldenTools: {
      count: tools.length,
      items: tools.slice(0, 30)
    },
    note: "Card do perfil: identidade + n\xEDvel + saldo + badges + golden tools (favoritos do aitag). O resto do perfil tem tool pr\xF3pria: imagens=sapiens_gallery, repert\xF3rio=sapiens_repertorio, personagens=sapiens_character, persona/MBTI=sapiens_persona action=my_profile."
  };
}

