async function decupagem(args) {
  const sessionToken = getSessionToken();
  if (args.action === "list") {
    const fichas = await convexQuery("decupagens:mcpListar", { sessionToken });
    const n = Array.isArray(fichas) ? fichas.length : 0;
    return {
      count: n,
      fichas,
      note: n === 0 ? "Acervo vazio. Rode o motor local (python tools/decupagem/decupa.py) e suba com action=save." : "R\xE9gua de cada refer\xEAncia. Pra ficha inteira (planos, luz, som): action=get slug=<slug>."
    };
  }
  if (args.action === "get") {
    if (!args.slug) throw new Error("sapiens_decupagem get: exige slug.");
    const ficha = await convexQuery("decupagens:mcpPegar", {
      sessionToken,
      slug: args.slug
    });
    if (!ficha) {
      return {
        found: false,
        note: `Nenhuma ficha com slug '${args.slug}'. Veja o acervo com action=list.`
      };
    }
    return { found: true, ficha };
  }
  if (args.action === "save") {
    if (!args.ficha) {
      throw new Error(
        "sapiens_decupagem save: exige `ficha` (o ficha.json inteiro que o motor gerou em tools/decupagem/fichas/<slug>/)."
      );
    }
    const f = args.ficha;
    const resumo2 = extrairResumo(f, args.slug);
    const r = await convexMutation("decupagens:mcpSalvar", {
      sessionToken,
      ...resumo2,
      ficha: f,
      nota: args.nota
    });
    return {
      ok: true,
      slug: resumo2.slug,
      criado: r?.criado ?? null,
      note: `Ficha de '${resumo2.titulo}' no acervo (${resumo2.planos} planos, plano mediano ${resumo2.durPlanoMediana}s, ${resumo2.escola}). Aparece no Lab em /experimentos/decupagem.`
    };
  }
  if (args.action === "note") {
    if (!args.slug || !args.nota) {
      throw new Error("sapiens_decupagem note: exige slug e nota.");
    }
    await convexMutation("decupagens:mcpSalvarNota", {
      sessionToken,
      slug: args.slug,
      nota: args.nota
    });
    return { ok: true, note: "Leitura anotada na ficha." };
  }
  if (args.action === "delete") {
    if (!args.slug) throw new Error("sapiens_decupagem delete: exige slug.");
    const r = await convexMutation("decupagens:mcpApagar", {
      sessionToken,
      slug: args.slug
    });
    return {
      ok: true,
      apagado: r?.apagado ?? false,
      note: r?.apagado ? "Ficha removida do acervo." : "N\xE3o havia ficha com esse slug."
    };
  }
  throw new Error(`sapiens_decupagem: action desconhecida '${args.action}'.`);
}
function extrairResumo(f, slugArg) {
  const fonte = f?.fonte ?? {};
  const cont = f?.container ?? {};
  const ritmo = f?.ritmo ?? {};
  const mov = f?.movimento ?? {};
  const luz = f?.luz ?? {};
  const som = f?.som ?? {};
  const cad = f?.cadencia ?? {};
  const titulo = String(fonte.titulo || fonte.arquivo || "sem titulo");
  const slug = (slugArg || slugify2(titulo)).slice(0, 80);
  if (!slug) throw new Error("sapiens_decupagem save: n\xE3o consegui derivar o slug.");
  const num = (x, def = 0) => typeof x === "number" && isFinite(x) ? x : def;
  const sinc = som?.sincronia_impacto ?? som?.sincronia_grade ?? som?.sincronia;
  return {
    slug,
    titulo: titulo.slice(0, 200),
    origem: String(fonte.origem || "local"),
    entrada: fonte.entrada ? String(fonte.entrada).slice(0, 500) : void 0,
    dur: num(cont.dur),
    planos: num(ritmo.planos),
    durPlanoMediana: num(ritmo.dur_mediana),
    escola: String(ritmo.escola || "").slice(0, 120),
    movTotalPct: num(mov.total_pct_s),
    movCameraPct: num(mov.camera_pct_s),
    movSujeitoPct: num(mov.sujeito_pct_s),
    registro: String(luz.registro || "").slice(0, 160),
    cadenciaReal: num(cad.cadencia_real),
    bpm: typeof som.bpm === "number" ? som.bpm : void 0,
    corteNoSom: sinc?.veredito ? String(sinc.veredito).slice(0, 160) : void 0
  };
}
function slugify2(s) {
  return s.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-zA-Z0-9\s-]/g, "").trim().toLowerCase().replace(/[\s_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60);
}

