async function publicidade(args) {
  const sessionToken = getSessionToken();
  if (args.action === "list") {
    const fichas = await convexQuery("adReferences:mcpListar", {
      sessionToken,
      ...args.trilha ? { trilha: args.trilha } : {},
      ...args.setor ? { setor: args.setor } : {},
      ...args.limite ? { limite: args.limite } : {}
    });
    const n = Array.isArray(fichas) ? fichas.length : 0;
    const semLeitura = Array.isArray(fichas) ? fichas.filter((f) => !f.temLeitura).length : 0;
    return {
      count: n,
      fichas,
      note: n === 0 ? "Nada nesse recorte ainda." : `${semLeitura} sem leitura escrita. A leitura \xE9 o que o acervo tem e uma busca no YouTube n\xE3o tem: action=note fonte=<f> externalId=<id> leitura="...".`
    };
  }
  if (args.action === "save") {
    if (!args.url) throw new Error("sapiens_publicidade save: exige url.");
    if (!args.titulo) throw new Error("sapiens_publicidade save: exige titulo.");
    const r = await convexMutation("adReferences:mcpGuardar", {
      sessionToken,
      url: args.url,
      titulo: args.titulo,
      ...args.marca ? { marca: args.marca } : {},
      ...args.trilha ? { trilha: args.trilha } : {},
      ...args.setor ? { setor: args.setor } : {},
      ...args.ano ? { ano: args.ano } : {},
      ...args.leitura ? { leitura: args.leitura } : {}
    });
    return {
      ...r,
      note: r?.novo ? "Guardada. Aparece pro membro em /dashboard/acervo?tab=referencias." : "J\xE1 estava no acervo; a ficha foi atualizada em vez de duplicar."
    };
  }
  if (args.action === "note") {
    if (!args.fonte || !args.externalId) {
      throw new Error("sapiens_publicidade note: exige fonte e externalId (v\xEAm do list).");
    }
    if (!args.leitura) throw new Error("sapiens_publicidade note: exige leitura.");
    return await convexMutation("adReferences:mcpAnotar", {
      sessionToken,
      fonte: args.fonte,
      externalId: args.externalId,
      leitura: args.leitura
    });
  }
  throw new Error(`sapiens_publicidade: action desconhecida "${args.action}".`);
}

