async function reference(args) {
  const sessionToken = getSessionToken();
  if (args.action === "resolve") {
    if (!args.handle) {
      return {
        error: "resolve exige `handle` (ex: img_..., vid_..., trk_...). \xC9 o ID que o usu\xE1rio copia no detalhe do item."
      };
    }
    const res = await convexQuery("assets:resolveHandle", {
      sessionToken,
      handle: args.handle
    });
    return {
      ...res,
      note: "Asset resolvido por posse + alcance. `mine`=seu, `isPublic`=p\xFAblico (seu ou de terceiro). Use a `url` como refer\xEAncia: em sapiens_image passe em referenceImageUrls; em sapiens_video em startImageUrl/endImageUrl (a url da casa j\xE1 \xE9 allowlistada). Se n\xE3o for seu nem p\xFAblico, o servidor recusa \u2014 n\xE3o force."
    };
  }
  if (args.action === "browse") {
    if (!args.bucket) {
      return {
        error: "browse exige `bucket` (history | favorites | videos | stock_video | acervo | characters | depth_map | pose_map)."
      };
    }
    if (args.bucket === "pose_map" && (args.semantic || args.similarTo)) {
      const res2 = await convexAction("poseRefs:mcpSearchByMeaning", {
        sessionToken,
        term: args.semantic ? args.term : void 0,
        similarTo: args.similarTo,
        people: args.people,
        limit: args.limit
      });
      const itens = res2?.items ?? [];
      return {
        bucket: "pose_map",
        modo: args.similarTo ? "parecidas" : "sentido",
        count: itens.length,
        items: itens,
        note: itens.length ? "Vizinhan\xE7a por SENTIDO, da mais parecida pra menos (`score` \xE9 a dist\xE2ncia). Cada item traz `descricao`: leia antes de escolher, \xE9 ela que diz o que o corpo faz. Use a `url` em sapiens_image referenceImageUrls." : "Nenhuma pose do seu banco chegou perto disso. Tente descrever o CORPO (apoio, dire\xE7\xE3o do tronco, o que os bra\xE7os fazem) em vez da cena, ou use browse com people/hasObject."
      };
    }
    const res = await convexAction("mcpReferences:referenceBrowse", {
      sessionToken,
      bucket: args.bucket,
      page: args.page,
      limit: args.limit,
      term: args.term,
      source: args.source,
      orientation: args.orientation,
      loopOnly: args.loopOnly,
      mode: args.mode,
      shadowSource: args.shadowSource,
      people: args.people,
      hasObject: args.hasObject,
      objeto: args.objeto,
      favoritesOnly: args.favoritesOnly,
      collection: args.collection,
      sort: args.sort
    });
    let note;
    if (args.bucket === "videos") {
      note = "Cada item \xE9 um v\xEDdeo seu (imageId reus\xE1vel em sapiens_video action=generate). Pra frame inicial/final de um v\xEDdeo NOVO use uma IMAGEM (bucket history/favorites/acervo/characters).";
    } else if (args.bucket === "stock_video") {
      note = "Clipes do Banco de V\xEDdeo da casa (B-roll pronto). Use a `url` do clipe: como refer\xEAncia de v\xEDdeo em sapiens_video (mesma rail do Meus V\xEDdeos), de fundo/atmosfera, ou baixe direto. orientation/durationSeconds/loopFriendly ajudam a escolher. N\xE3o s\xE3o imagem: N\xC3O servem de frame inicial/final (pra frame use uma IMAGEM).";
    } else if (args.bucket === "depth_map" || args.bucket === "deepshadow") {
      note = "Guias de movimento (mapa de profundidade). Use a `url` em sapiens_video referenceVideoUrls: a coreografia e a c\xE2mera do clipe guiam o take. `thumbnailUrl` \xE9 s\xF3 preview (a soma com esqueleto), nunca mande ela como driving. Teto de dura\xE7\xE3o varia por motor.";
    } else if (args.bucket === "pose_map") {
      note = "Poses do SEU banco privado (mapa de profundidade de corpo). Use a `url` em sapiens_image referenceImageUrls pra guiar a POSE da figura, do mesmo jeito que o depth_map guia o movimento no v\xEDdeo. Cada item diz `people` (solo/dupla/grupo), `objeto` (null = corpo limpo), `favorite` e `useCount`; pra recortar, mande people/hasObject/objeto em vez de tentar pela busca escrita. Pedido vago ('uma pose boa pra isso') come\xE7a por favoritesOnly=true ou sort='used': \xE9 a curadoria que o dono j\xE1 fez, e ela vale mais que mil op\xE7\xF5es. `thumbnailUrl` \xE9 s\xF3 preview da grade. \xC9 material privado seu: a pe\xE7a gerada a partir dele \xE9 gera\xE7\xE3o normal e publica normal, mas a pose em si n\xE3o \xE9 acervo p\xFAblico da casa.";
    } else if (args.bucket === "acervo" || args.bucket === "characters") {
      note = "S\xE3o refer\xEAncias p\xFAblicas: use a `url` (characters trazem mainImageUrl + imageUrls) em sapiens_image referenceImageUrls, ou em sapiens_video startImageUrl/endImageUrl. N\xE3o s\xE3o suas, ent\xE3o N\xC3O entram em sourceImageIds.";
    } else {
      note = "Pra usar como refer\xEAncia: em sapiens_image passe o imageId em sourceImageIds (ou a url em referenceImageUrls); em sapiens_video passe startImageId/endImageId (ou startImageUrl/endImageUrl).";
    }
    if (args.term && !res?.items?.length) {
      note = `Nenhuma pe\xE7a deste banco casou com "${args.term}". O banco pode ter outras: tente um termo mais curto (a busca casa por peda\xE7o de palavra), outro bucket, ou browse sem \`term\`. Se o usu\xE1rio te deu o ID da pe\xE7a (img_\u2026, vid_\u2026), use action=resolve.`;
    }
    return { ...res, note };
  }
}

