      sessionToken,
      slug: args.slug,
      nome: args.nome,
      grupo: args.grupo,
      artigo: args.artigo,
      lang: args.lang,
      ordem: args.ordem,
      quem: args.quem,
      mae: args.mae,
      contas: args.contas,
      galerias: args.galerias,
      fichaIds: args.fichaIds,
      contaNaCasa: args.contaNaCasa,
