  isActive: external_exports.boolean().optional().describe("settings: liga/desliga o link (desligado responde 'indispon\xEDvel')."),
  password: external_exports.string().optional().describe("settings: senha pra ver o conte\xFAdo (string vazia remove a senha)."),
  requireLogin: external_exports.boolean().optional().describe("settings: exige conta Sapiens logada pra abrir o link.")
