function extractTitle(html) {
  const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (m && m[1]) {
    const cleaned = m[1].replace(/\s+/g, " ").trim();
    if (cleaned) return cleaned;
  }
  return void 0;
}
async function resolveHtml(args) {
  if (typeof args.html === "string" && args.html.trim()) {
    return args.html;
  }
  if (args.htmlPath) {
    if (isRemoteContext()) {
      throw new Error(
        "htmlPath s\xF3 funciona no MCP instalado (stdio). No remoto, mande o conte\xFAdo em `html`."
      );
    }
    return await readFile2(args.htmlPath, "utf8");
  }
  throw new Error(
    "Falta o HTML: passe `html` (o conte\xFAdo) ou `htmlPath` (caminho de um .html local)."
  );
}
async function uploadBlob(sessionToken, html) {
  const uploadUrl = await convexMutation(
    "mcpExtras:mcpGenerateShareUploadUrl",
    { sessionToken }
  );
  const res = await fetch(uploadUrl, {
    method: "POST",
    headers: { "Content-Type": "text/html" },
    body: html
  });
  if (!res.ok) {
    throw new Error(`Upload pro storage falhou: HTTP ${res.status} ${res.statusText}`);
  }
  const body = await res.json();
  if (!body.storageId) throw new Error("Upload n\xE3o retornou storageId.");
  return { storageId: body.storageId, sizeBytes: Buffer.byteLength(html, "utf8") };
}
async function shareDrop(args) {
  const sessionToken = getSessionToken();
  switch (args.action) {
    case "list": {
      const rows = await convexQuery("mcpExtras:mcpListShareDrops", {
        sessionToken
      });
      return {
        count: rows.length,
        links: rows.map((r) => ({ ...r, url: `${SHARE_BASE_URL}/s/${r.code}` }))
      };
    }
    case "upload": {
      const html = await resolveHtml(args);
      const title = args.title ?? extractTitle(html) ?? "Untitled";
      const { storageId, sizeBytes } = await uploadBlob(sessionToken, html);
      const res = await convexMutation(
        "mcpExtras:mcpCreateShareDrop",
        { sessionToken, storageId, title, sizeBytes, contentType: "text/html" }
      );
      return {
        code: res.code,
        title: res.title,
        url: `${SHARE_BASE_URL}/s/${res.code}`,
        sizeBytes
      };
    }
    case "update": {
      const code2 = need(args.code, "code");
      const html = await resolveHtml(args);
      const newTitle = args.keepTitle ? void 0 : args.title ?? extractTitle(html);
      const { storageId, sizeBytes } = await uploadBlob(sessionToken, html);
      const res = await convexMutation("mcpExtras:mcpReplaceShareDrop", {
        sessionToken,
        code: code2,
        newStorageId: storageId,
        sizeBytes,
        contentType: "text/html",
        newTitle
      });
      return {
        code: res.code,
        title: res.title,
        url: `${SHARE_BASE_URL}/s/${res.code}`,
        sizeBytes: res.sizeBytes,
        updatedAt: res.updatedAt
      };
    }
    case "delete": {
      const code2 = need(args.code, "code");
      return await convexMutation("mcpExtras:mcpDeleteShareDrop", {
        sessionToken,
        code: code2
      });
    }
    case "settings": {
      const code2 = need(args.code, "code");
      return await convexMutation("mcpExtras:mcpSetShareDropSettings", {
        sessionToken,
        code: code2,
        isActive: args.isActive,
        password: args.password,
        requireLogin: args.requireLogin
      });
    }
  }
}

