function readSkillResource(uri) {
  const name = skillNameFromUri(uri);
  if (!name) return null;
  const text = getSkillMd(name);
  if (!text) return null;
  return { contents: [{ uri, mimeType: "text/markdown", text }] };
}

// src/tools/skill.ts
var skillSchema = external_exports.object({
  action: external_exports.enum(["list", "get"]).default("list").describe(
    "'list' devolve o \xEDndice (slug + quando usar) das skills da casa. 'get' devolve o SKILL.md inteiro de uma."
  ),
  name: external_exports.string().optional().describe(
    "Slug da skill no action=get. Ex: 'musica', 'video', 'voz-da-casa'. Rode action=list se n\xE3o souber."
  )
});
async function skill(args) {
  const action = args.action ?? "list";
  if (action === "list") {
    const skills = listSkills();
    return {
      count: skills.length,
      skills,
      note: "Chame action=get name=<slug> pra ler a skill inteira antes de operar o fluxo."
    };
  }
  const name = args.name?.trim();
  if (!name) {
    return {
      error: "action=get exige 'name'. Rode action=list pra ver os slugs.",
      available: listSkills().map((s) => s.name)
    };
  }
  const md = getSkillMd(name);
  if (!md) {
    return {
      error: `Skill '${name}' n\xE3o existe.`,
      available: listSkills().map((s) => s.name)
    };
  }
  return { name, content: md };
}

